/* Illustrative external policy projections, separate from contextual evaluations. */
const externalPolicies=[
{id:'closure',name:'Change closure approval',source:'ServiceNow',operation:'Close change',operationKey:'change.close',resource:'Normal production changes',selector:'Change type = normal · environment = production',actor:'Change operator',summary:'ServiceNow requires two approvals and closure evidence. A source script adds an unknown requirement.',sourceRef:'sn-policy / closure-81',revision:'source-81',age:'6 min ago',fresh:true,coverage:'Partial',coverageNote:'The integration read two requirements. One script condition is unknown. The source can apply other rules.',requirements:[{name:'Approval threshold',rule:'At least 2 distinct approvers',expression:'distinct approvals ≥ 2',knowledge:'Described',origin:'Approval configuration',result:'Not satisfied',evidence:'1 distinct approver reported'}, {name:'Supporting evidence',rule:'Closure evidence must be attached',expression:'closure evidence is present',knowledge:'Described',origin:'Required-field metadata',result:'Satisfied',evidence:'Evidence attachment reported'}, {name:'Closure script',rule:'Additional source-defined condition',expression:'Condition unavailable',knowledge:'Unknown',origin:'Script reference exposed; body unavailable',result:'Not reported',evidence:'The response did not identify this check'}],evaluation:{subject:'CHG-2041',operation:'Validate change closure',actor:'Change operator',result:'Rejected',when:'8 min ago',input:'input-digest / 4f20',reason:'ServiceNow reported insufficient approval evidence.',revision:'Not returned by source',note:'The source returned this result before the latest policy read. The integration matched the checks to known requirements. The evaluated revision is unknown.'}},
{id:'branch',name:'Protected branch merge',source:'GitHub',operation:'Merge pull request',operationKey:'pull_request.merge',resource:'payments-api / main',selector:'Repository = payments-api · target branch = main',actor:'Repository contributor',summary:'Merging into main requires two approving reviews and successful build and security checks.',sourceRef:'gh-policy / branch-main',revision:'source-23',age:'1 min ago',fresh:true,coverage:'Known requirements',coverageNote:'The source exposed these branch requirements. The integration did not read organization rules or user exceptions.',requirements:[{name:'Required reviews',rule:'At least 2 approving reviews',expression:'approving reviews ≥ 2',knowledge:'Described',origin:'Branch review settings'}, {name:'Required checks',rule:'build and security must pass',expression:'build = success AND security = success',knowledge:'Described',origin:'Required status-check settings'}],evaluation:null},
{id:'maintenance',name:'Production change window',source:'ServiceNow',operation:'Start change',operationKey:'change.start',resource:'Payments service / production',selector:'Service = payments · environment = production',actor:'Change operator',summary:'The last known policy requires an approved start time. Read the source again to get the current schedule.',sourceRef:'sn-policy / payments-window',revision:'source-17',age:'38 min ago',fresh:false,coverage:'Known requirements',coverageNote:'The window requirement was described at discovery time. The expired source data cannot confirm the current window.',requirements:[{name:'Allowed start time',rule:'Start within a published maintenance window',expression:'requested start ∈ approved windows',knowledge:'Described',origin:'Service maintenance schedule'}],evaluation:null}
];
let externalTab='requirements',externalRefreshes={};
function externalFresh(p){return p.fresh||!!externalRefreshes[p.id]}
function externalAge(p){return externalRefreshes[p.id]?'Just now':p.age}
function externalKnowledge(p){return `${badge(p.coverage,p.coverage==='Partial'?'warn':'blue')}<span class="sub">${p.requirements.filter(r=>r.knowledge==='Described').length} requirement${p.requirements.filter(r=>r.knowledge==='Described').length===1?'':'s'} described${p.requirements.some(r=>r.knowledge==='Unknown')?' · 1 unknown':''}</span>`}
function externalPolicyTable(){const rows=externalPolicies.filter(p=>(!filter||p.source===filter)&&(!query||`${p.name} ${p.source} ${p.operation} ${p.resource} ${p.requirements.map(r=>r.rule).join(' ')}`.toLowerCase().includes(query.toLowerCase())));return `<div class="table-wrap"><table class="external-table"><thead><tr><th>External policy / enforced by</th><th>Governs</th><th>Requirements</th><th>Discovery result</th><th>Last source read</th></tr></thead><tbody>${rows.map(p=>`<tr><td><button class="record-link" data-action="contract" data-id="${p.id}">${p.name}</button><span class="sub">${p.source}</span></td><td><strong>${p.operation}</strong><span class="sub">${p.resource}</span></td><td>${p.requirements.map(r=>`<span class="external-rule-line ${r.knowledge==='Unknown'?'unknown':''}"><span aria-hidden="true">${r.knowledge==='Unknown'?'?':'·'}</span>${r.rule}</span>`).join('')}</td><td>${externalKnowledge(p)}</td><td>${badge(externalFresh(p)?'Source data current':'Source data expired',externalFresh(p)?'good':'warn')}<span class="sub">${externalAge(p)}</span></td></tr>`).join('')}</tbody></table>${rows.length?'':'<div class="empty">No external policies match this operation, resource, or requirement.</div>'}</div>`}
function externalPolicyScreen(){const id=location.hash.slice(1).split('/')[2],p=externalPolicies.find(p=>p.id===id);if(p)return externalPolicyDetail(p);return `${head('External policies','External systems enforce these requirements. Integrations read their descriptions.')}<div class="external-summary"><span><strong>3</strong> external policies</span><span><strong>2</strong> enforcement systems</span><span><strong>1</strong> unknown condition</span><span><strong>${externalPolicies.filter(p=>!externalFresh(p)).length}</strong> expired observation${externalPolicies.filter(p=>!externalFresh(p)).length===1?'':'s'}</span></div>${panel('Discovered requirements',toolbar('Search policy, resource, operation, or requirement',['ServiceNow','GitHub'])+externalPolicyTable())}<p class="external-footnote">The integration can miss source requirements. Current source data can be incomplete. Expired source data does not mean the policy stopped applying.</p>`}
function externalRequirementView(p){return `<div class="external-detail-grid"><section class="panel"><div class="panel-head"><h2>Requirement model</h2><span class="muted">${p.requirements.length} discovered conditions</span></div><div class="external-flow"><div><small>REQUEST</small><strong>${p.operation}</strong><span>${p.resource}</span></div><span class="flow-arrow" aria-hidden="true">→</span><div><small>REQUIREMENTS</small><strong>${p.requirements.filter(r=>r.knowledge==='Described').length} described${p.requirements.some(r=>r.knowledge==='Unknown')?' + 1 unknown':''}</strong><span>Details below</span></div><span class="flow-arrow" aria-hidden="true">→</span><div><small>DECISION AUTHORITY</small><strong>${p.source}</strong><span>Evaluates the actual request</span></div></div><div class="table-wrap"><table><thead><tr><th>Condition</th><th>Required value</th><th>Source information</th></tr></thead><tbody>${p.requirements.map(r=>`<tr><td><strong>${r.name}</strong>${r.knowledge==='Unknown'?badge('Unknown requirement','warn'):''}</td><td><span>${r.rule}</span><span class="sub mono">${r.expression}</span></td><td><span>${r.origin}</span><span class="sub">${r.knowledge==='Unknown'?'Cannot predict this condition locally':'Requirement description available'}</span></td></tr>`).join('')}</tbody></table></div><div class="external-limit"><strong>Limits of this source read</strong><p>${p.coverageNote}</p></div></section><aside class="panel"><div class="panel-head"><h2>Source details</h2></div><dl class="external-facts"><div><dt>Enforced by</dt><dd>${p.source}</dd></div><div><dt>Integration node</dt><dd>${p.source==='GitHub'?'identity':'payments'}-prod-integrate / node-01</dd></div><div><dt>Source reference</dt><dd class="mono">${p.sourceRef}</dd></div><div><dt>Observed source revision</dt><dd class="mono">${p.revision}</dd></div><div><dt>Last source read</dt><dd>${externalAge(p)}</dd></div><div><dt>Description format</dt><dd>External policy format / v3</dd></div></dl><div class="external-aside-action"><button class="btn" data-external-refresh="${p.id}">Read sample source ${icon('refresh')}</button><p class="muted">A source read updates the record. Unknown requirements remain unknown.</p></div></aside></div>`}
function externalEvaluationView(p){const e=p.evaluation;if(!e)return `<section class="panel"><div class="external-no-evaluation"><h2>No evaluation observed</h2><p>We have a policy description, but no ${p.source} result for a specific ${p.operation.toLowerCase()} request in this sample.</p><p>Describe the requirements independently of whether any request has passed them.</p><button class="btn" data-external-tab="requirements">Inspect requirements</button></div></section>`;return `<section class="panel"><div class="external-eval-heading">${badge(e.result,'bad')}<div><h2>${e.subject} · ${e.operation}</h2><p>${e.reason}</p></div><span>${e.when}</span></div><div class="external-eval-context"><div><small>REQUEST IDENTITY</small><strong>${e.actor}</strong></div><div><small>REQUEST DATA ID</small><strong class="mono">${e.input}</strong></div><div><small>EVALUATED SOURCE REVISION</small><strong>${e.revision}</strong></div></div><div class="table-wrap"><table><thead><tr><th>Known requirement</th><th>Observed evidence</th><th>Check result from reported data</th></tr></thead><tbody>${p.requirements.map(r=>`<tr><td>${r.rule}</td><td>${r.evidence}</td><td>${badge(r.result,r.result==='Not satisfied'?'bad':r.result==='Satisfied'?'good':'warn')}</td></tr>`).join('')}</tbody></table></div><div class="external-limit"><strong>Result limits</strong><p>${e.note}</p><p>This result applies to the recorded identity, request data, and time. It does not confirm that the change was closed.</p></div></section>`}
function externalHistoryView(p){return `<section class="panel"><div class="panel-head"><h2>Source history</h2></div><div class="table-wrap"><table><thead><tr><th>Observed</th><th>Source revision</th><th>Recorded change</th><th>Coverage</th></tr></thead><tbody>${externalRefreshes[p.id]?`<tr><td>Just now</td><td class="mono">${p.revision}</td><td>Simulated refresh; described requirements unchanged.</td><td>${p.coverage}</td></tr>`:''}<tr><td>${p.age}</td><td class="mono">${p.revision}</td><td>${p.requirements.length} condition descriptions recorded from discovery.</td><td>${p.coverage}</td></tr></tbody></table></div><div class="external-limit"><p>Earlier revisions are not available in this sample. The source did not provide the time when the policy took effect.</p></div></section>`}
function externalPolicyDetail(p){return `<a class="external-back" href="#workspace/contracts">${icon('back')} External policies</a>${head(p.name,p.summary)}<div class="external-scope-strip"><div><small>REQUEST ACTION</small><strong>${p.operation}</strong><span class="mono">${p.operationKey}</span></div><div><small>APPLIES TO</small><strong>${p.resource}</strong><span>${p.selector}</span></div><div><small>REQUEST IDENTITY</small><strong>${p.actor}</strong><span>Enforced by ${p.source}</span></div><div><small>OBSERVATION</small>${badge(externalFresh(p)?'Current':'Expired',externalFresh(p)?'good':'warn')}<span>${externalAge(p)} · ${p.coverage.toLowerCase()}</span></div></div>${!externalFresh(p)?'<div class="external-stale">This view shows the last known requirements. Read the source again before you use the schedule.</div>':''}<nav class="external-tabs" aria-label="External policy details">${[['requirements','Requirements'],['evaluation','Latest evaluation'],['history','Source history']].map(([id,label])=>`<button data-external-tab="${id}" aria-pressed="${externalTab===id}">${label}</button>`).join('')}</nav>${externalTab==='requirements'?externalRequirementView(p):externalTab==='evaluation'?externalEvaluationView(p):externalHistoryView(p)}`}
function openContract(id){if(current.concept==='workspace'){externalTab='requirements';close();location.hash='#workspace/contracts/'+id;return}openContractLegacy(id)}
document.addEventListener('click',e=>{const t=e.target.closest('[data-external-tab]');if(t){externalTab=t.dataset.externalTab;render()}const r=e.target.closest('[data-external-refresh]');if(r){externalRefreshes[r.dataset.externalRefresh]=true;render();toast('The sample source read is complete. Requirements and unknown conditions did not change.')}});
